def esle(abone, konu):
    a, k = abone.split("/"), konu.split("/")
    for i, s in enumerate(a):
        if s == "#":
            return True
        if i >= len(k):
            return False
        if s != "+" and s != k[i]:
            return False
    return len(a) == len(k)

