import json, struct

def bas(major, n):
    if n < 24:    return bytes([major << 5 | n])
    if n < 256:   return bytes([major << 5 | 24, n])
    if n < 65536: return bytes([major << 5 | 25]) + struct.pack(">H", n)
    return bytes([major << 5 | 26]) + struct.pack(">I", n)

def cbor(o):
    if isinstance(o, int):   return bas(0, o)
    if isinstance(o, str):   return bas(3, len(o)) + o.encode()
    if isinstance(o, list):  return bas(4, len(o)) + b"".join(cbor(x) for x in o)
    if isinstance(o, dict):
        return bas(5, len(o)) + b"".join(cbor(k) + cbor(v) for k, v in o.items())
    raise TypeError(o)

