MTU, MAC, IPHC = 127, 25, 6
ILK = MTU - MAC - 4 - IPHC
SON = MTU - MAC - 5

def parca(n):
    if n <= ILK:
        return 1
    return 1 + -(-(n - ILK) // SON)

